"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["20618"],{70800(e,t,i){i.d(t,{Ay:()=>a,RM:()=>o});var n=i(74848),s=i(28453);let o=[];function r(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"endless-individual-stock-climaxes-under-a-sluggish-index",children:"Endless Individual Stock Climaxes Under a Sluggish Index"})}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"2008/1/2 15:12:24"}),"\n"]}),"\n",(0,n.jsxs)("div",{style:{color:"#009900",fontWeight:"500",fontSize:"18px"},children:[(0,n.jsx)(t.p,{children:"As the title suggests, the first day's market action continues to foreshadow the characteristics of this year's market: not much juice in the index, but plenty of juice in individual stocks. This has been repeatedly discussed since the end of last year. To put it in a more punchy, dynamic slogan: Sluggish index, climaxing stocks."}),(0,n.jsx)(t.p,{children:"Of course, the index won't stay sluggish indefinitely. The index will often exhibit spasmodic trends \u2014 suddenly jerking up, then trembling non-stop. Two jerks, ten trembles \u2014 that's roughly what you'll encounter frequently on the index this year. The day the index stops having spasms and charges forward relentlessly, that's when you should actually be careful."}),(0,n.jsx)(t.p,{children:"Technically, the index continues the oscillation of the 5-minute hub from late last year. Until a third-type buy or sell point appears, the trembling continues."}),(0,n.jsx)(t.p,{children:"As for individual stocks, there's not much to say. Several of the stocks this ID has mentioned hit new highs above the 6124-point level again today. For individual stocks, the high from the 6124 level serves as a strength-weakness dividing line \u2014 once it's broken through and held, the rally becomes even fiercer. For example, 600737 is a perfect case: the high from the 6124-point decline was around 14 yuan. After breaking through and holding, it's now up above 20 yuan."}),(0,n.jsx)(t.p,{children:"Of course, for specific individual stocks, there will inevitably be pullbacks after breaking through that level. The best approach to handle such pullbacks is to trade short-term swings in the direction of the trend, extracting price differences without losing your position. However, this demands high operational skill. Another approach is to set a medium-term reference like the 5-week moving average \u2014 as long as the pullback doesn't break below it, just hold. For example, look at 600737: it swung back and forth, scaring countless people out, but after its breakout and pullback, when did it ever effectively break below the 5-week moving average?"}),(0,n.jsx)(t.p,{children:"There will be bread on the table. This year, the earlier you act, the safer it is. Right now, for individual stocks, opportunities far outweigh risks. Even if a stock's yearly candlestick ends up bearish, it still needs to form an upper shadow first. But as we get past mid-year, things become uncertain. This year is about stockpiling grain early \u2014 if there's a second opportunity, great; if not, you won't go hungry either, as the year's bread will already be secured."}),(0,n.jsx)(t.p,{children:"Never chase stocks at their highs. If you missed the earlier moves, look among low-priced and second-tier stocks for those that are slow to react but have capital stationed inside. Everyone's human, everyone needs to eat. As long as capital is stationed there, business will eventually open up \u2014 otherwise, who's going to pay for the year's expenses?"}),(0,n.jsx)(t.p,{children:"As for the big-cap stocks, if your technical skills are good, bleed them during those spasm jerks. When they're trembling, you don't necessarily need to play along."}),(0,n.jsx)(t.p,{children:"Signing off for now, goodbye."})]})]})}function a(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(r,{...e})}):r(e)}},5781(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>a,contentTitle:()=>l,toc:()=>c,assets:()=>h});var n=JSON.parse('{"id":"timeline/economics/stockshigh","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/economics/stockshigh.md","sourceDirName":"timeline/economics","slug":"/timeline/economics/stockshigh","permalink":"/en/timeline/economics/stockshigh","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"stockshigh","title":"","hide_table_of_contents":true,"sidebar_label":"Nonstop Individual Stock Climaxes Amid Index Weakness (2008/1/2 15:12:24)"},"sidebar":"timelineSidebar","previous":{"title":"Top Priority for the 2008 Securities Market: Chairman Shang, It\'s Time for a Promotion. (2008/1/1 17:38:18)","permalink":"/en/timeline/economics/2008firstpriority"},"next":{"title":"Mao Zedong and Lu Xun (2008/1/2 19:58:17)","permalink":"/en/timeline/confucius/maoandluxun"}}'),s=i(74848),o=i(28453),r=i(70800);let a={id:"stockshigh",title:"",hide_table_of_contents:!0,sidebar_label:"Nonstop Individual Stock Climaxes Amid Index Weakness (2008/1/2 15:12:24)"},l,h={},c=[...r.RM];function d(e){return(0,s.jsx)(r.Ay,{})}function u(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,t,i){i.d(t,{R:()=>r,x:()=>a});var n=i(96540);let s={},o=n.createContext(s);function r(e){let t=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),n.createElement(o.Provider,{value:t},e.children)}}}]);